document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("loader-wrapper"),t=document.getElementById("main-card"),n=document.getElementById("clock-container"),d=()=>{const e=new Date;document.getElementById("month-name").textContent=["JANUARY","FEBRUARY","MARCH","APRIL","MAY","JUNE","JULY","AUGUST","SEPTEMBER","OCTOBER","NOVEMBER","DECEMBER"][e.getMonth()],document.getElementById("day-name").textContent=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][e.getDay()],document.getElementById("day-number").textContent=e.getDate(),document.getElementById("year").textContent=e.getFullYear()},a=()=>{const e=new Date,t=String(e.getHours()).padStart(2,"0"),n=String(e.getMinutes()).padStart(2,"0"),d=String(e.getSeconds()).padStart(2,"0");document.getElementById("digital-clock").textContent=`${t}:${n}:${d}`};d(),a(),setInterval(a,1e3),setInterval(d,36e5),window.addEventListener("load",()=>{setTimeout(()=>{e.style.opacity="0",t.style.display="block",n.style.display="block",e.style.display="none"},1e3)})});